<?php
require_once __DIR__.'/../bootstrap/app.php';use GymPro\Services\ClassService;require_role('TRAINER');$u=current_user();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{if($u['Status']!=='ACTIVE')throw new RuntimeException('Your trainer account is not active.');ClassService::create((int)$u['TrainerID'],$_POST);set_flash('success','Class submitted for super-admin approval.');redirect('trainer/classes.php');}catch(Throwable $e){$errors[]=$e->getMessage();}}
$rows=db_all("SELECT c.*,(SELECT COUNT(*) FROM ENROLLMENT e WHERE e.ClassID=c.ClassID AND e.Status='ENROLLED') Enrolled FROM CLASS c WHERE c.TrainerID=? ORDER BY c.DateOfClass DESC,c.StartTime",'i',[$u['TrainerID']]);$pageTitle='My classes';$pageSubtitle='Create classes and track approval';include ROOT_PATH.'/includes/header.php';?>
<?php if($errors):?><div class="alert alert-danger" role="alert"><?=e(implode(' ',$errors))?></div><?php endif;?><div class="split-layout"><div class="form-card"><h2 class="section-title">Create class</h2><form method="post"><?=csrf_field()?><div class="form-grid"><div class="form-group form-full"><label for="name">Class name</label><input id="name" name="name" required></div><div class="form-group"><label for="date">Date</label><input id="date" type="date" name="date" min="<?=date('Y-m-d')?>" required></div><div class="form-group"><label for="capacity">Capacity</label><input id="capacity" type="number" name="capacity" min="1" max="10" value="10" required></div><div class="form-group"><label for="start">Start</label><input id="start" type="time" name="start" required></div><div class="form-group"><label for="end">End</label><input id="end" type="time" name="end" required></div><div class="form-group"><label for="specialization">Specialization</label><input id="specialization" name="specialization" required></div><div class="form-group"><label for="rate">Commission basis (Rs.)</label><input id="rate" type="number" name="rate" min="0" step="0.01" value="0"></div><div class="form-group form-full"><label for="description">Description</label><textarea id="description" name="description"></textarea></div></div><div class="form-actions"><button class="btn btn-primary" type="submit">Submit for approval</button></div></form></div><div class="table-wrap"><table class="data-table"><thead><tr><th scope="col">Class</th><th scope="col">Schedule</th><th scope="col">Seats</th><th scope="col">Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['ClassName'])?></strong><br><small><?=e($r['Specialization'])?></small></td><td><?=e($r['DateOfClass'])?><br><?=e(substr($r['StartTime'],0,5))?>–<?=e(substr($r['EndTime'],0,5))?></td><td><?=$r['Enrolled']?> / <?=min(10,(int)$r['Capacity'])?></td><td><span class="badge <?=$r['Status']==='SCHEDULED'?'badge-green':($r['Status']==='REJECTED'?'badge-red':'badge-amber')?>"><?=e($r['Status'])?></span></td></tr><?php endforeach;?></tbody></table></div></div>
<?php include ROOT_PATH.'/includes/footer.php';?>
